PAGES=[]
for slug,c in C.items():
    n=c['n']; N=n[0].upper()+n[1:]
    secs=[('which-link','Which link do you need?',ul(['Disabled or suspended notice: appeal from that screen. See '+a('/guides/instagram-account-suspended-appeal/','Instagram appeal')+' or '+a('/guides/facebook-account-disabled-appeal/','Facebook appeal')+'.','Hacked: the hacked links below, then the local reporting bodies if money or identity is involved.','Ad account restricted: Business Support Home, as an admin. See '+a('/meta-ad-account-appeal-links-directory/','ad account links')+'.','Lost a Facebook Page to another Business Portfolio: '+a('/facebook-page-recovery/','Facebook Page recovery')+'.'])),
     ('official','Official Meta links',linkrows(BASE)),
     ('local',f'Where to report in {n}',linkrows(c['rows']+([ACE] if c['eu'] else [])))]
    if c['eu']: secs.append(('dsa','Your EU rights','<p>Under the EU Digital Services Act, Meta must give you a statement of reasons when it restricts or disables your account, and an internal appeal. After that, you can take the decision to a certified out-of-court dispute body such as Appeals Centre Europe. These routes are free or low-cost for users and run alongside Meta’s own appeal. See '+a('/dsa-appeal-right-instagram-facebook/','DSA appeal rights')+' and '+a('/statement-of-reasons-dsa-account-ban/','statement of reasons')+'.</p>'))
    if c['note']: secs.append(('local-tip',f'Tip for {n}',f'<p>{c["note"]}</p>'))
    if c['lang']: secs.append(('language','In your language','<p>'+a(c['lang'][1],c['lang'][2]+' version of the Meta appeal links')+'.</p>'))
    secs.append(('before','Before you open any link',ol(['Screenshot the full notice, including the date.','Use your usual phone or computer and network, without a VPN.','Appeal once, in plain words.','Do not make a new account while you wait.','Never pay anyone for a “private” appeal link. There is none.'])))
    PAGES.append(P(slug=f'meta-appeal-links-{slug}',svc='ig',offer=False,crumb=('Meta appeal links','/meta-appeal-links-and-forms-directory/'),
     navrel=[('/meta-appeal-links-and-forms-directory/','Meta appeal links'),('/how-to-contact-meta-about-a-disabled-account/','How to contact Meta'),('/instagram-appeal-links-and-forms-directory/','Instagram appeal links'),('/facebook-appeal-links-and-forms-directory/','Facebook appeal links'),('/pricing/','Pricing'),('/what-to-send-for-account-recovery-help/','What to send us')],
     title=f'Meta Appeal Links for {N} (2026): Instagram, Facebook, Ads + Where to Report',short=f'Meta appeal links {n}',
     desc=f'Official Instagram, Facebook and Meta ad account appeal links for people in {n}, plus the local authorities to report hacking and fraud'+(' and your EU DSA options.' if c['eu'] else '.'),
     h1=f'Meta appeal links for {n}.',lede=f'The official Instagram, Facebook and ad account routes, and the {"local and EU " if c["eu"] else "local "}bodies that matter when an account is hacked or used for fraud.',
     answer=f'<strong>The Meta appeal routes in {n} are the same as everywhere: appeal a disabled or suspended Instagram or Facebook account from the notice you see when you log in, use instagram.com/hacked or facebook.com/hacked for takeovers, and request ad account reviews in Business Support Home.</strong> Meta has no general support phone number. '+('As an EU user you also have Digital Services Act rights, including an out-of-court dispute body after Meta’s appeal. ' if c['eu'] else '')+f'If money or identity was stolen, report it to the local authorities listed below. If the official route fails, Unbanz handles Instagram ($800) and Facebook ($900) cases, paid upfront with a 100% refund if it fails.',
     cards=[('Same routes','In-app notice, hacked pages, Business Support Home.'),('Local reporting','For hacking and money lost.'),('EU rights' if c['eu'] else 'No phone line','Statement of reasons and dispute bodies.' if c['eu'] else 'Meta has no general support number.')],
     sections=secs,
     faqs=[(f'Does Meta have a phone number in {n}?','No general support line for accounts. Numbers claiming to be Meta support are usually scams.'),(f'Can I appeal in my own language?','Yes. Write the appeal in the language you are most precise in.')]+([('What is Appeals Centre Europe?','An independent, certified out-of-court dispute body for EU users, used after the platform’s own appeal.')] if c['eu'] else [])+[(f'Does Unbanz work with clients in {n}?','Yes. Instagram $800, Facebook $900, Facebook Page $600, ad account $1,200, paid upfront with a 100% refund if it fails.')],
     related=[('/meta-appeal-links-and-forms-directory/','Meta appeal links directory'),('/how-to-contact-meta-about-a-disabled-account/','How to contact Meta'),('/account-recovery-links-directory-all-platforms/','All-platform recovery links')]))
